from common import *
src('igeeks-v3'); dom('angular')
topic('Components & Templates')
M('b','k',"Which decorator marks a class as an Angular component?","@Component","@Directive","@Injectable","@NgModule","@Component ties a class to a template, styles and a selector.")
M('b','k',"Which syntax displays a component property in a template?","{{ title }}","[[ title ]]","<% title %>","${ title }","Double curly braces are interpolation, evaluated against the component class.")
M('b','k',"Which syntax binds a DOM property to a component value?","[disabled]=\"isBusy\"","(disabled)=\"isBusy\"","{disabled}=\"isBusy\"","bind-disabled(isBusy)","Square brackets mean property binding, from the component to the template.")
M('b','k',"Which syntax listens to a click event in a template?","(click)=\"save()\"","[click]=\"save()\"","onclick=\"save()\"","{click}=\"save()\"","Parentheses mean event binding, from the template to the component.")
M('b','k',"What does [(ngModel)] provide?","Two-way data binding between a form control and a property","One-way binding to the template","Event binding only","A route guard","The banana-in-a-box syntax combines [ngModel] and (ngModelChange). It requires FormsModule.")
M('b','k',"Which control-flow block shows content only when a condition is true in modern Angular templates?","@if (condition) { ... }","*ngShow=\"condition\"","<if condition>","[if]=\"condition\"","Built-in control flow (@if, @for, @switch) replaces the older structural directives such as *ngIf.")
M('b','k',"Which control-flow block repeats a template for each item and needs a track expression?","@for (item of items; track item.id) { ... }","@each (item in items) { ... }","*ngLoop=\"let item of items\"","@repeat items","track tells Angular how to identify items so it can reuse DOM nodes when the list changes.")
M('b','k',"What is the Angular CLI command that creates a new component named user-card?","ng generate component user-card","ng new user-card","ng add user-card","ng create user-card","ng g c user-card is the short form.")
topic('Services & DI')
M('b','k',"Which decorator makes a class available for dependency injection?","@Injectable","@Component","@Input","@Pipe","@Injectable({ providedIn: 'root' }) registers a tree-shakable singleton service.")
M('b','k',"How does a component usually receive a service?","Through constructor or inject() dependency injection","By creating it with new","By importing it into the template","By a global variable","Angular's injector creates the service and supplies it where it is requested.")
topic('Components & Templates')
M('b','k',"Which decorator lets a parent pass data into a child component?","@Input","@Output","@ViewChild","@HostBinding","An @Input property receives a value bound with [name]=\"value\" in the parent template.")
M('b','k',"Which mechanism lets a child notify its parent?","@Output with an EventEmitter","@Input","A route parameter","A pipe","The parent listens with (eventName)=\"handler($event)\".")
M('b','k',"What does a pipe do in a template?","Transforms a value for display, such as {{ price | currency }}","Connects two components","Creates a route","Loads a service","Pipes format or convert values without changing the source data.")
topic('Routing')
M('b','k',"Which directive creates a navigation link that uses the Angular router?","routerLink","href","navigateTo","ngLink","routerLink changes the route without reloading the page.")
M('b','k',"Which element shows the component matched by the current route?","<router-outlet>","<ng-view>","<route-view>","<ng-container>","The router renders the matched component in the router-outlet.")
topic('Forms')
M('i','k',"What is the difference between template-driven and reactive forms?","Reactive forms are defined in the component class with FormGroup and FormControl","Template-driven forms are defined in services","Reactive forms cannot be validated","They are the same","Reactive forms give explicit, testable control. Template-driven forms rely on directives such as ngModel.")
M('i','k',"Which validator makes a form control mandatory?","Validators.required","Validators.notEmpty","Validators.mandatory","Validators.present","Validators.required marks the control invalid when empty.")
topic('RxJS & HTTP')
M('i','k',"What does HttpClient.get() return?","An Observable","A Promise","A plain object","A string","HttpClient methods return cold observables. The request is sent when something subscribes.")
M('i','k',"What does the async pipe do?","Subscribes to an Observable or Promise in the template and unsubscribes automatically","Makes a function asynchronous","Delays rendering by one second","Caches HTTP calls","It avoids manual subscribe and unsubscribe code and works well with OnPush.")
M('i','k',"Which RxJS operator turns each value into a new Observable and cancels the previous inner one?","switchMap","map","mergeMap","tap","switchMap is typical for type-ahead search, where only the latest request matters.")
topic('Services & DI')
M('i','k',"What does providedIn: 'root' do for a service?","Registers a single shared instance for the whole application","Creates a new instance per component","Makes the service private to the root component","Loads it only on the home route","The root injector holds one instance that all consumers share. Unused services can be tree-shaken.")
topic('Routing')
M('i','k',"Which router feature stops a user from opening a route unless a condition holds?","A route guard such as canActivate","A pipe","An interceptor","A resolver","Guards return true, false or a UrlTree to allow, block or redirect navigation.")
topic('Change Detection & Signals')
M('a','k',"What does ChangeDetectionStrategy.OnPush do?","Checks the component only when an input reference changes, an event occurs, an async pipe emits or a signal it reads changes","Disables change detection","Runs change detection every second","Checks the component only once","OnPush reduces checks. Mutating an object in place without changing its reference is not noticed.")
M('a','k',"Which function creates a writable signal with an initial value in Angular?","signal(0)","useSignal(0)","new Signal(0)","state(0)","count = signal(0) creates a signal. Read it by calling count() and change it with set or update.")
M('a','k',"What does computed(() => a() * 2) return?","A read-only signal that recalculates when a changes","A writable signal","An Observable","A Promise","computed values are lazy and memoised. They update only when a dependency signal changes.")
M('a','k',"What is effect() used for with signals?","Running side effects whenever the signals read inside it change","Creating a signal","Formatting a template value","Replacing services","Use effects sparingly, for things like logging or syncing to storage, and not to derive state (use computed).")
M('a','k',"In which lifecycle hook is it safe to read the @Input values for the first time?","ngOnInit","constructor","ngOnDestroy","ngAfterViewChecked","Inputs are set after construction. ngOnInit runs once after the first ngOnChanges.")
M('a','k',"A component subscribes to an Observable in ngOnInit and never unsubscribes. What may happen?","A memory leak and callbacks running after the component is destroyed","Nothing, Angular always unsubscribes","A compile error","The Observable completes automatically","Use the async pipe, takeUntilDestroyed, or unsubscribe in ngOnDestroy. HTTP observables complete on their own.")
M('a','k',"What is the main benefit of lazy loading a route with loadComponent or loadChildren?","The route's code is downloaded only when it is first visited","The route renders faster once loaded","It avoids using the router","It disables guards","Smaller initial bundles mean faster startup.")
topic('RxJS & HTTP')
M('a','k',"Which operator should be used to run several independent HTTP requests in parallel and get all results together?","forkJoin","concatMap","switchMap","exhaustMap","forkJoin waits for every source to complete and emits the last value of each as an array.")
M('a','k',"What does an HttpInterceptor allow?","Inspecting or modifying every outgoing request and incoming response, for example to add an auth header","Changing the router","Compiling templates","Generating components","Interceptors form a chain and are registered with provideHttpClient(withInterceptors([...])).")
M('a','k',"What is the difference between a cold and a hot Observable?","A cold observable runs its producer for each subscriber, a hot one shares an already running producer","Hot ones are faster","Cold ones never complete","They are identical","HttpClient requests are cold: two subscribers send two requests unless the result is shared with shareReplay.")
topic('Services & DI')
M('a','k',"What does the inject() function offer compared with constructor injection?","It can be used in field initialisers and functions that run in an injection context","It creates a new instance each time","It works outside Angular","It replaces providers","const http = inject(HttpClient) works in components, services, guards and interceptors.")
topic('Components & Templates')
M('a','k',"What does ng-content do in a component template?","Projects the content placed between the component's tags into that spot","Creates a container","Imports a module","Loads a template file","Content projection lets a wrapper component accept arbitrary child content.")
topic('Forms')
M('a','k',"Why might you use a custom async validator?","To validate against the server, for example checking whether a username is taken","To validate quickly with regex","To disable validation","To style inputs","Async validators return an Observable or Promise and run after sync validators pass.")
M('a','k',"What is the purpose of trackBy / the track expression for lists?","To let Angular reuse DOM nodes for unchanged items instead of recreating the whole list","To sort items","To filter items","To animate items","Without a stable identity, re-created data causes DOM nodes to be destroyed and rebuilt.")
